"""Seed PostgreSQL with Country Sales data for BI Platform.

Creates a 'country_sales' table in the existing database with the provided
sales dataset.

Usage: python seed_countrysales.py
"""

import os

from dotenv import load_dotenv
from sqlalchemy import create_engine, text

load_dotenv(override=True)

DB_URL = os.environ.get(
    "DATABASE_URL",
    "postgresql+psycopg2://neondb_owner:npg_TkpfuRq10JbB@ep-royal-fog-ay5q53xp.c-5.us-east-2.aws.neon.tech/neondb?sslmode=require",
)
engine = create_engine(DB_URL, pool_size=5)

print("Dropping existing tables if present...")
with engine.begin() as conn:
    conn.execute(text("DROP TABLE IF EXISTS country_sales"))

print("Creating 'country_sales' table...")
with engine.begin() as conn:
    conn.execute(text("""
        CREATE TABLE country_sales (
            id SERIAL PRIMARY KEY,
            region TEXT,
            country TEXT,
            product_category TEXT,
            product_name TEXT,
            customer_segment TEXT,
            order_priority TEXT,
            date TEXT,
            order_id TEXT,
            ship_date TEXT,
            quantity INTEGER,
            unit_price REAL,
            cost REAL,
            total_revenue REAL,
            total_cost REAL,
            profit REAL
        )
    """))

