for r in rows:
    remapped.append({
        "region": r["region"],
        "country": r["country"],
        "product_category": r["item_type"],
        "product_name": r["item_type"],
        "customer_segment": r["sales_channel"],
        "order_priority": r["order_priority"],
        "date": r["order_date"],
        "order_id": r["order_id"],
        "ship_date": r["ship_date"],
        "quantity": r["units_sold"],
        "unit_price": r["unit_price"],
        "cost": r["total_cost"],
        "total_revenue": r["total_revenue"],
        "total_cost": r["total_cost"],
        "profit": r["total_profit"],
    })
with engine.begin() as conn:
    conn.execute(
        text("""
            INSERT INTO country_sales
                (region, country, product_category, product_name, customer_segment,
                 order_priority, date, order_id, ship_date, quantity, unit_price,
                 cost, total_revenue, total_cost, profit)
            VALUES (:region, :country, :product_category, :product_name, :customer_segment,
                    :order_priority, :date, :order_id, :ship_date, :quantity, :unit_price,
                    :cost, :total_revenue, :total_cost, :profit)
        """),
        remapped,
    )

with engine.connect() as conn:
    count = conn.execute(text("SELECT COUNT(*) FROM country_sales")).scalar()
    print(f"Verification: country_sales has {count} rows")

print("Done! 'country_sales' table created and seeded.")
